class ImageCache(context: Context) {
    private val maxBytes = (ActivityManagerCompat.getMemoryClass(context) * 1024 * 1024 / 8).toInt()

    private val cache = object : LruCache<String, Bitmap>(maxBytes) {
        override fun sizeOf(key: String, value: Bitmap) = value.byteCount
        override fun entryRemoved(evicted: Boolean, key: String, old: Bitmap, new: Bitmap?) {
            if (evicted) old.recycle()   // only when we hold sole ownership
        }
    }

    @Synchronized fun get(url: String, width: Int, height: Int): Bitmap? =
        cache.get(key(url, width, height))

    @Synchronized fun put(url: String, bitmap: Bitmap) {
        cache.put(key(url, bitmap.width, bitmap.height), bitmap)
    }

    private fun key(url: String, w: Int, h: Int) = "$url@${w}x$h"
}

