@Composable
fun SimpleRow(modifier: Modifier = Modifier, content: @Composable () -> Unit) {
    Layout(content, modifier) { measurables, constraints ->
        val placeables = measurables.map { m ->
            m.measure(constraints.copy(minWidth = 0, minHeight = 0))
        }
        val width = placeables.sumOf { it.width }.coerceAtMost(constraints.maxWidth)
        val height = placeables.maxOfOrNull { it.height }?.coerceAtMost(constraints.maxHeight) ?: 0
        layout(width, height) {
            var x = 0
            placeables.forEach { p ->
                p.placeRelative(x, 0)
                x += p.width
            }
        }
    }
}

