class MiniStateFlow<T>(initial: T) {
    @Volatile private var state: T = initial
    private val subs = mutableListOf<Pair<T?, (T) -> Unit>>()
    private val lock = Any()

    val value: T get() = state

    fun subscribe(onChange: (T) -> Unit) {
        synchronized(lock) {
            subs += state to onChange
            onChange(state)             // immediate replay of current value
        }
    }

    fun update(next: T) {
        synchronized(lock) {
            if (state == next) return      // no-op, keeps dedup trivial
            state = next
            subs.removeAll { (last, cb) -> if (last == next) { true } else { cb(next); false } }
        }
    }
}

