class KeyValueStore<K, V>(private val maxSize: Int = 1024) {
    private val map = java.util.concurrent.ConcurrentHashMap<K, V>()

    fun get(key: K): V? = map[key]

    fun put(key: K, value: V) {
        map[key] = value
        // evict when over budget (best-effort; note it's not atomic with the put)
        while (map.size > maxSize) {
            map.keys.firstOrNull()?.let { map.remove(it) }
        }
    }

    fun getOrPut(key: K, default: () -> V): V = map.computeIfAbsent(key) { default() }
}

