suspend fun <T> withRetry(
    initialMs: Long = 200L,
    maxMs: Long = 30_000L,
    maxAttempts: Int = 5,
    shouldRetry: (Throwable) -> Boolean = { true },
    block: suspend () -> T,
): T {
    var attempt = 0
    while (true) {
        try {
            return block()
        } catch (e: Throwable) {
            if (attempt >= maxAttempts - 1 || !shouldRetry(e)) throw e
            val backoff = minOf(maxMs, initialMs * (1L shl attempt))
            kotlinx.coroutines.delay(Random.nextLong(0, backoff + 1))  // full jitter
            attempt++
        }
    }
}

