class WorkQueue<T>(
    capacity: Int = 16,
    workers: Int = 4,
    private val scope: CoroutineScope,
) {
    private val channel = Channel<suspend () -> Unit>(
        capacity, onBufferOverflow = BufferOverflow.SUSPEND)

    init {
        repeat(workers) {
            scope.launch {
                for (job in channel) runCatching { job() }
            }
        }
    }

    suspend fun submit(job: suspend () -> Unit) {
        channel.send(job)   // suspends when full — backpressure
    }

    fun shutdown() = channel.close()
}

